mapper.select:
SELECT primary_key, send_order_number, vender, vender_name, consignee_name, delivery_address, sender, send_time,
logistics_number,
logistics_info, send_order_title, package_info, temp_detail, packaged,enterprise_code, delete_flag
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'

    AND send_order_number LIKE '%'|| #{sendOrderNumber} ||'%'


    AND vender_name LIKE '%'|| #{venderName} ||'%'


    AND consignee_name LIKE '%'|| #{consigneeName} ||'%'


    AND sender IN

        #{sender}



    AND logistics_number LIKE '%'|| #{logisticsNumber} ||'%'


    AND send_time >= #{sendTimePreDate}


    AND send_time <= #{sendTimePostDate}


    ${dataScopeParams.dataScope}

ORDER BY id DESC

SELECT primary_key, send_order_number, vender, vender_name, consignee_name, delivery_address, sender, send_time,
logistics_number,
logistics_info, send_order_title, package_info, temp_detail,packaged, enterprise_code, delete_flag
FROM ${tableName}
WHERE
enterprise_code= #{enterpriseCode}
AND delete_flag= 'f'
AND primary_key= #{outPartSendOrderCode}

    ${dataScopeParams.dataScope}

mapper.update:
UPDATE ${tableName}
SET temp_detail = NULL
WHERE enterprise_code = #{model.enterpriseCode}
  AND primary_key = #{model.outPartSendOrderCode}
  AND temp_detail IS NOT NULL

UPDATE ${tableName}
SET temp_detail = #{model.tempDetail}
WHERE enterprise_code = #{model.enterpriseCode}
  AND primary_key = #{model.outPartSendOrderCode}

UPDATE ${tableName}
SET send_order_number   = #{model.sendOrderNumber},
    logistics_number = #{model.logisticsNumber},
    send_order_title = #{model.sendOrderTitle},
    package_info        = #{model.packageInfo},
    packaged = #{model.packaged},
    temp_detail         = NULL
WHERE enterprise_code = #{model.enterpriseCode}
  AND primary_key = #{model.outPartSendOrderCode}

mapper.select:
SELECT COUNT(id)
FROM ${tableName}
WHERE enterprise_code = #{enterpriseCode}
  AND primary_key != #{excludeSendOrderCode}
  AND send_order_number = #{sendOrderNumber}
  AND delete_flag = 'f'
